+export type Plan = {
+  order: string[];
+  layers: string[][];
+  earliest: Record<string, { start: number; finish: number }>;
+  totalDuration: number;
+  criticalPath: string[];
+};
+
+type Task = Required<InputTask>;
+
+function fail(message: string): never {
+  throw new Error(message);
+}
+
+function compareSequences(left: string[], right: string[]): number {
+  for (let index = 0; index < Math.min(left.length, right.length); index += 1) {
+    const comparison = left[index].localeCompare(right[index]);
+    if (comparison !== 0) return comparison;
+  }
+  return left.length - right.length;
+}
+
+export function validateInput(value: unknown): Task[] {
+  if (typeof value !== "object" || value === null || Array.isArray(value)) {
+    fail("Input must be an object with a tasks array");
+  }
+
+  const tasks = (value as { tasks?: unknown }).tasks;
+  if (!Array.isArray(tasks)) fail("tasks must be an array");
+
+  const ids = new Set<string>();
+  const validated: Task[] = tasks.map((task, index) => {
+    if (typeof task !== "object" || task === null || Array.isArray(task)) {
+      fail(`tasks[${index}] must be an object`);
+    }
+    const candidate = task as Partial<InputTask>;
+    if (typeof candidate.id !== "string" || candidate.id.length === 0) {
+      fail(`tasks[${index}].id must be a non-empty string`);
+    }
+    if (ids.has(candidate.id)) fail(`Duplicate task id: ${candidate.id}`);
+    ids.add(candidate.id);
+    if (typeof candidate.duration !== "number" || !Number.isFinite(candidate.duration) || candidate.duration < 0) {
+      fail(`tasks[${index}].duration must be a finite non-negative number`);
+    }
+    if (candidate.dependsOn !== undefined && !Array.isArray(candidate.dependsOn)) {
+      fail(`tasks[${index}].dependsOn must be an array`);
+    }
+    const dependsOn = candidate.dependsOn ?? [];
+    if (!dependsOn.every((dependency) => typeof dependency === "string")) {
+      fail(`tasks[${index}].dependsOn must contain only strings`);
+    }
+    if (new Set(dependsOn).size !== dependsOn.length) {
+      fail(`tasks[${index}].dependsOn contains duplicate ids`);
+    }
+    if (dependsOn.includes(candidate.id)) fail(`Task ${candidate.id} cannot depend on itself`);
+    return { id: candidate.id, duration: candidate.duration, dependsOn };
+  });
+
+  for (const task of validated) {
+    for (const dependency of task.dependsOn) {
+      if (!ids.has(dependency)) fail(`Task ${task.id} depends on unknown task: ${dependency}`);
+    }
+  }
+  return validated;
+}
+
+function findCycle(tasks: Task[], byId: Map<string, Task>): string[] | undefined {
+  const state = new Map<string, "visiting" | "visited">();
+  const stack: string[] = [];
+
+  const visit = (id: string): string[] | undefined => {
+    state.set(id, "visiting");
+    stack.push(id);
+    for (const dependency of [...byId.get(id)!.dependsOn].sort()) {
+      if (state.get(dependency) === "visiting") {
+        return [...stack.slice(stack.indexOf(dependency)), dependency];
+      }
+      if (state.get(dependency) !== "visited") {
+        const cycle = visit(dependency);
+        if (cycle) return cycle;
+      }
+    }
+    stack.pop();
+    state.set(id, "visited");
+    return undefined;
+  };
