+  for (const task of [...tasks].sort((left, right) => left.id.localeCompare(right.id))) {
+    if (!state.has(task.id)) {
+      const cycle = visit(task.id);
+      if (cycle) return cycle;
+    }
+  }
+  return undefined;
+}
