+    if (comparison !== 0) return comparison;
+  }
+  return left.length - right.length;
+}
+
+export function validateInput(value: unknown): Task[] {
+  if (typeof value !== "object" || value === null || Array.isArray(value)) {
+    fail("Input must be an object with a tasks array");
+  }
+
+  const tasks = (value as { tasks?: unknown }).tasks;
+  if (!Array.isArray(tasks)) fail("tasks must be an array");
+
+  const ids = new Set<string>();
+  const validated: Task[] = tasks.map((task, index) => {
+    if (typeof task !== "object" || task === null || Array.isArray(task)) {
+      fail(`tasks[${index}] must be an object`);
+    }
+    const candidate = task as Partial<InputTask>;
+    if (typeof candidate.id !== "string" || candidate.id.length === 0) {
+      fail(`tasks[${index}].id must be a non-empty string`);
+    }
+    if (ids.has(candidate.id)) fail(`Duplicate task id: ${candidate.id}`);
+    ids.add(candidate.id);
+    if (typeof candidate.duration !== "number" || !Number.isFinite(candidate.duration) || candidate.duration < 0) {
+      fail(`tasks[${index}].duration must be a finite non-negative number`);
+    }
+    if (candidate.dependsOn !== undefined && !Array.isArray(candidate.dependsOn)) {
+      fail(`tasks[${index}].dependsOn must be an array`);
+    }
+    const dependsOn = candidate.dependsOn ?? [];
+    if (!dependsOn.every((dependency) => typeof dependency === "string")) {
+      fail(`tasks[${index}].dependsOn must contain only strings`);
+    }
+    if (new Set(dependsOn).size !== dependsOn.length) {
+      fail(`tasks[${index}].dependsOn contains duplicate ids`);
+    }
+    if (dependsOn.includes(candidate.id)) fail(`Task ${candidate.id} cannot depend on itself`);
+    return { id: candidate.id, duration: candidate.duration, dependsOn };
+  });
+
+  for (const task of validated) {
+    for (const dependency of task.dependsOn) {
+      if (!ids.has(dependency)) fail(`Task ${task.id} depends on unknown task: ${dependency}`);
+    }
+  }
+  return validated;
+}
+
+function findCycle(tasks: Task[], byId: Map<string, Task>): string[] | undefined {
+  const state = new Map<string, "visiting" | "visited">();
+  const stack: string[] = [];
+
+  const visit = (id: string): string[] | undefined => {
+    state.set(id, "visiting");
+    stack.push(id);
+    for (const dependency of [...byId.get(id)!.dependsOn].sort()) {
+      if (state.get(dependency) === "visiting") {
+        return [...stack.slice(stack.indexOf(dependency)), dependency];
+      }
+      if (state.get(dependency) !== "visited") {
+        const cycle = visit(dependency);
+        if (cycle) return cycle;
+      }
+    }
+    stack.pop();
+    state.set(id, "visited");
+    return undefined;
+  };
+
+  for (const task of [...tasks].sort((left, right) => left.id.localeCompare(right.id))) {
+    if (!state.has(task.id)) {
+      const cycle = visit(task.id);
+      if (cycle) return cycle;
+    }
+  }
+  return undefined;
+}
+
+export function buildPlan(input: unknown): Plan {
+  const tasks = validateInput(input);
+  const byId = new Map(tasks.map((task) => [task.id, task]));
+  const cycle = findCycle(tasks, byId);
+  if (cycle) fail(`Dependency cycle detected: ${cycle.join(" -> ")}`);
+
+  const dependents = new Map(tasks.map((task) => [task.id, [] as string[]]));
+  const remaining = new Map(tasks.map((task) => [task.id, task.dependsOn.length]));
+  for (const task of tasks) {
+    for (const dependency of task.dependsOn) dependents.get(dependency)!.push(task.id);
+  }
+
+  const ready = tasks.filter((task) => task.dependsOn.length === 0).map((task) => task.id).sort();
+  const order: string[] = [];
+  while (ready.length > 0) {
+    const id = ready.shift()!;
+    order.push(id);
+    for (const dependent of dependents.get(id)!) {
+      const count = remaining.get(dependent)! - 1;
+      remaining.set(dependent, count);
+      if (count === 0) {
+        ready.push(dependent);
+        ready.sort();
+      }
+    }
+  }
+
+  const earliest: Plan["earliest"] = {};
+  const paths = new Map<string, string[]>();
+  const layerById = new Map<string, number>();
+  const layers: string[][] = [];
+  for (const id of order) {
+    const task = byId.get(id)!;
+    let start = 0;
+    let path: string[] = [];
+    let layer = 0;
+    for (const dependency of task.dependsOn) {
+      const dependencyTiming = earliest[dependency];
+      const candidatePath = paths.get(dependency)!;
+      if (dependencyTiming.finish > start || (dependencyTiming.finish === start && compareSequences(candidatePath, path) < 0)) {
+        start = dependencyTiming.finish;
+        path = candidatePath;
+      }
+      layer = Math.max(layer, layerById.get(dependency)! + 1);
+    }
+    earliest[id] = { start, finish: start + task.duration };
+    paths.set(id, [...path, id]);
+    layerById.set(id, layer);
+    (layers[layer] ??= []).push(id);
+  }
+  for (const layer of layers) layer.sort();
+
+  let totalDuration = 0;
+  let criticalPath: string[] = [];
+  for (const id of order) {
+    const finish = earliest[id].finish;
+    const path = paths.get(id)!;
+    if (finish > totalDuration || (finish === totalDuration && compareSequences(path, criticalPath) < 0)) {
+      totalDuration = finish;
+      criticalPath = path;
+    }
+  }
+  return { order, layers, earliest, totalDuration, criticalPath };
+}
+
+async function main(): Promise<void> {
+  const args = process.argv.slice(2);
+  if (args.length !== 2 || args[0] !== "plan") {
+    fail("Usage: bun run src/cli.ts plan INPUT.json");
+  }
+  let input: unknown;
+  try {
+    input = JSON.parse(await Bun.file(args[1]).text());
+  } catch (error) {
+    const detail = error instanceof Error ? error.message : String(error);
+    fail(`Unable to read valid JSON from ${args[1]}: ${detail}`);
+  }
+  process.stdout.write(`${JSON.stringify(buildPlan(input))}\n`);
+}
+
+if (import.meta.main) {
+  main().catch((error) => {
+    process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
+    process.exit(1);
+  });
+}

