+import { buildPlan } from "../src/cli";
+
+test("plans dependencies deterministically", () => {
+  expect(buildPlan({
+    tasks: [
+      { id: "deploy", duration: 1, dependsOn: ["build", "test"] },
+      { id: "test", duration: 2, dependsOn: ["lint"] },
+      { id: "lint", duration: 1 },
+      { id: "build", duration: 3, dependsOn: ["lint"] },
+      { id: "docs", duration: 0 },
+    ],
+  })).toEqual({
+    order: ["docs", "lint", "build", "test", "deploy"],
+    layers: [["docs", "lint"], ["build", "test"], ["deploy"]],
+    earliest: {
+      docs: { start: 0, finish: 0 },
+      lint: { start: 0, finish: 1 },
+      build: { start: 1, finish: 4 },
+      test: { start: 1, finish: 3 },
+      deploy: { start: 4, finish: 5 },
+    },
+    totalDuration: 5,
+    criticalPath: ["lint", "build", "deploy"],
+  });
+});
+
+test("chooses the lexicographically smallest equal critical path", () => {
+  expect(buildPlan({
+    tasks: [
+      { id: "z", duration: 1 },
+      { id: "a", duration: 1 },
+      { id: "end", duration: 1, dependsOn: ["z", "a"] },
+    ],
+  }).criticalPath).toEqual(["a", "end"]);
+});
+
+test("reports a deterministic concrete cycle", () => {
+  expect(() => buildPlan({
+    tasks: [
+      { id: "b", duration: 1, dependsOn: ["c"] },
+      { id: "c", duration: 1, dependsOn: ["a"] },
+      { id: "a", duration: 1, dependsOn: ["b"] },
+    ],
+  })).toThrow("Dependency cycle detected: a -> b -> c -> a");
+});
+
+test("rejects invalid dependencies", () => {
+  expect(() => buildPlan({ tasks: [{ id: "a", duration: 1, dependsOn: ["missing"] }] }))
+    .toThrow("Task a depends on unknown task: missing");
+});

